public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(SalesTable, ACBookTable):
            this.ACUpdateBookSalesLine();
            break;
    }
}

public void ACUpdateBookSalesLine()
{
    SalesLine salesLine;

    while select forupdate salesLine
                where salesLine.SalesId == this.SalesId
    {
        salesLine.ACBookTable = this.ACBookTable;
        ttsbegin;
        if(salesLine.validateWrite())
        {
            salesLine.update();

        }
        ttscommit;
    }
    this.ACResearchIfNeeded();
}

public void ACResearchIfNeeded()
{
    FormDataSource formDataSource = FormDataUtil::getFormDataSource(this);

    if(formDataSource)
    {
        formDataSource.research(true);
    }
}

public Common ACFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(ACBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.ACGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Author));

    return refTableLookup.performFormLookup();
}
